\begin{aligned}
& \|(1-{T}_{N}{T}^{up}-\tilde{W}_{N})[U^+]\|_{L^2(\tilde{\Gamma}_r)}
\\&\leq \frac{1}{2}\left\|\sum_{n=0}^\infty\sum_{k=1}^{2n+1}(1-{\Phi}_N^\wedge(n)\sigma_n)\big(U_r^+\big)^\wedge(n,k)\frac{1}{r}Y_{n,k}\right\|_{L^2(\Omega_r)}
\\&\quad+\frac{1}{2}\left\|\sum_{n=0}^\infty\sum_{k=1}^{2n+1}\tilde{\Psi}_{N}^\wedge(n)\big(U_r^+\big)^\wedge(n,k)\frac{1}{r}Y_{n,k}\right\|_{L^2(\Omega_r)}
\\&\quad+\frac{1}{2}\left\|\sum_{n=0}^\infty\sum_{k=1}^{2n+1}(1-\tilde{\Phi}_N^\wedge(n))\big(U_r^+\big)^\wedge(n,k)\frac{1}{r}Y_{n,k}\right\|_{L^2(\Omega_r)}
\\&\quad+\left\|\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}_{N}(\cdot,y) U^+(y)d\omega(y)\right\|_{L^2(\Omega_r)}
\\&\leq\sup_{n=0,1,\ldots}\frac{\big|1-\tilde{\Phi}_N^\wedge(n)\big|}{2\big(n+\frac{1}{2}\big)^s}\|U^+\|_{\mathcal{H}_s(\Omega_r)}+\sup_{n=0,1,\ldots}\frac{\big|1-{\Phi}_{N}^\wedge(n)\sigma_n\big|}{2\big(n+\frac{1}{2}\big)^s}\|U^+\|_{\mathcal{H}_s(\Omega_r)}
\\&\quad+\frac{1}{2}\sup_{n=0,1,\ldots}\big|\tilde{\Psi}_{N}^\wedge(n)\big|\|U^+\|_{L^2(\Omega_r)}+2\sqrt{2}\pi r^2\big\|\tilde{\Psi}_{N}\big\|_{L^2([-1,1-\rho])}\|U^+\|_{L^2(\Omega_r)}.
\end{aligned}

{\begin{aligned}
\mathcal{F}(\Phi_N,\tilde{\Psi}_N)=&\sum_{n=0}^{\lfloor\kappa N\rfloor}\tilde{\alpha}_{N,n}\big|1-\tilde{\Phi}_{N}^\wedge(n)\big|^2+\sum_{n=0}^{N}\alpha_{N,n}\big|1-{\Phi}_{N}^\wedge(n)\sigma_n\big|^2
\\&+\beta_N\sum_{n=0}^{N}\big|\Phi_N^\wedge(n)\big|^2+8\pi^2 r^4\big\|\tilde{\Psi}_N\big\|^2_{L^2([-1,1-\rho])},
\end{aligned}}

\begin{aligned}
&\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}_{N}(\cdot,y) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\leq\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}^{Sh}_{N}(\cdot,y) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\quad\,+\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\left(\tilde{\Psi}^{Sh}_{N}(\cdot,y)-\tilde{\Psi}_{N}(\cdot,y)\right) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\leq\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}^{Sh}_{N}(\cdot,y) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\quad\,+2\pi r^2\|\tilde{\Psi}^{Sh}_{N}-\tilde{\Psi}_{N}\|_{L^2([-1,1-\rho])} \|U^+\|_{L^1(\Omega_r)},
\end{aligned}

\begin{aligned}
&\big\|\tilde{\Psi}^{Sh}_{N}-\tilde{\Psi}_{N}\big\|_{L^2([-1,1-\rho])}^2
\\&\leq\sum_{n=0}^{\lfloor\kappa N\rfloor}\left(\frac{2n+1}{4\pi}\right)^2\left|\tilde{\Psi}_N^\wedge(n)-\left(\tilde{\Psi}^{Sh}_N\right)^\wedge(n)\right|^2\|P_n\|_{L^2([-1,1])}^2
\\&\leq\sum_{n=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{8\pi^2}\left|\left|\tilde{\Phi}_{N}^\wedge(n)-1\right|+\left|{\Phi}_N^\wedge(n)\sigma_n-1\right|\chi_{[0,N]}(n)\right|^2
\\&=\sum_{n=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{8\pi^2}\mathcal{O}\left(N^{-2(1+\delta)}\right)=\mathcal{O}\left(N^{-2\delta}\right).
\end{aligned}

{\begin{aligned}
\mathcal{F}(\mathbf{\Phi}_N,\tilde{\mathbf{\Psi}}_N)=&\sum_{n=0}^{\lfloor\kappa N\rfloor}\tilde{\alpha}_{N,n}\big|1-\tilde{\mathbf{\Phi}}_{N}^\wedge(n)\big|^2+\sum_{n=0}^{N}\alpha_{N,n}\big|1-{\mathbf{\Phi}}_{N}^\wedge(n)\sigma_n\big|^2
\\&+\beta_N\sum_{n=0}^{N}\big|\mathbf{\Phi}_N^\wedge(n)\big|^2+8\pi^2 r^4\big\|\tilde{\mathbf{\Psi}}_N\big\|^2_{L^2([-1,1-\rho])}.
\end{aligned}}

From satellite measurements we obtain data $F_1$ on a spherical orbit $\Omega_R=\{x\in\mathbb{R}^3:|x|=R\}$ and from ground or near-ground measurements data $F_2$ in a subregion $\Gamma_r$ of the spherical Earth surface $\Omega_r$ of radius $r<R$ (cf. Figure \ref{fig:datasit}). The problem to solve is
\begin{align}
\Delta U=0,\quad&\textnormal{ in }\Omega_r^{ext}, \\U=F_1,\quad&\textnormal{ on }\Omega_R, \\U=F_2,\quad&\textnormal{ on }\Gamma_r, \end{align}
with $\Omega_r^{ext}=\{x\in\mathbb{R}^3:|x|>r\}$ denoting the space exterior to the sphere $\Omega_r$.

Throughout this paper, we use an approximation $U_N$ of $U^+$ of the form 
\begin{align} {U_N={T}_N[F_1]+{\tilde{W}}_N[F_2].}
\end{align}

It is motivated by spherical multiscale representations as introduced in \cite{schneider98} and \cite{freewind}: $T_N$ reflects a regularized version of the downward continuation operator, acting as a scaling transform on $\Omega_R$ with the convolution kernel 
\begin{align} {\Phi_N(x,y)=\sum_{n=0}^N\sum_{k=1}^{2n+1}\Phi_N^\wedge(n)\frac{1}{r}Y_{n,k}\left(\xi\right)\frac{1}{R}Y_{n,k}\left(\eta\right).}
\end{align}

In order to refine the approximation with local data we use the operator $\tilde{W}_N$, which acts as a wavelet transform on $\Gamma_r$ with the convolution kernel
\begin{align} {\tilde{\Psi}_N(x,y)=\sum_{n=0}^{\lfloor\kappa N\rfloor}\sum_{k=1}^{2n+1}\tilde{\Psi}_N^\wedge(n)\frac{1}{r}Y_{n,k}\left(\xi\right)\frac{1}{r}Y_{n,k}\left(\eta\right), }
\end{align}
where $\kappa>1$ is a fixed constant (reflecting the higher resolution desired for the refinement).

Aside from the space  $L^2(\Omega_r)$ of square-integrable functions on $\Omega_r$, we also need the Sobolev space $\mathcal{H}_s(\Omega_r)$, $s\geq 0$. It is defined by
\begin{align} \mathcal{H}_s(\Omega_r)=\left\{F\in L^2(\Omega_r):\|F\|_{\mathcal{H}_s(\Omega_r)}^2=\sum_{n=0}^\infty\sum_{k=1}^{2n+1}\Big(n+\textnormal{\footnotesize $\frac{1}{2}$}\Big)^{2s} \big|F_r^\wedge(n,k)\big|^2<\infty\right\},
\end{align}
where $F_r^\wedge(n,k)$ denotes the Fourier coefficient of degree $n$ and order $k$, i.e.,
\begin{align}
F_r^\wedge(n,k)=\int_{\Omega_r}F(y)\frac{1}{r}Y_{n,k}\left(\frac{y}{|y|}\right)d\omega(y).
\end{align}

The downward continuation operator $T^{down}$ and acts in the following way:  
\begin{align} U^+(x)={T}^{down}[F_1](x)=\int_{\Omega_R}K^{down}(x,y) U^+(y)d\omega(y),\quad x\in\Omega_r,
\end{align}
with 
\begin{align} K^{down}(x,y)&=\sum_{n=0}^\infty\sum_{k=1}^{2n+1}\frac{1}{\sigma_n}\frac{1}{r}Y_{n,k}\left(\xi\right)\frac{1}{R}Y_{n,k}\left(\eta\right).
\end{align}

Following the course of \cite{freeden99} and \cite{schneider98}, we assume $\Phi_N$ to be a scaling kernel of the form \eqref{eqn:phin} with truncation index $\lfloor\kappa N\rfloor$ and symbols $\Phi_N^\wedge(n)$ that satisfy
\begin{itemize}
\item[(a)] $\lim_{N\to\infty}\Phi_N^\wedge(n)=\frac{1}{\sigma_n}$, uniformly with respect to $n=0,1,\ldots$,
\item[(b)] $\sum_{n=0}^\infty \frac{2n+1}{4\pi} \big|\Phi_N^\wedge(n)\big|< \infty$,  for all $N=0,1,\ldots$.
\end{itemize}

The bounded scaling transform $T_N:L^2(\Omega_R)\to L^2(\Omega_r)$ is then defined via 
\begin{align} {{T}_N[F_1](x)=\int_{\Omega_R}\Phi_N(x,y) F_1(y)d\omega(y),\quad x\in\Omega_r,}
\end{align}
and represents an approximation of $T^{down}[F_1]$.

We slightly modify the symbol $\tilde{\Psi}_N^\wedge(n)$ by use of the auxiliary symbol $\tilde{\Phi}_N^\wedge(n)$, so that it reads  
\begin{align}
{\tilde{\Psi}_N^\wedge(n)=\tilde{\Phi}_N^\wedge(n)-\Phi_N^\wedge(n)\sigma_n.}
\end{align}

The auxiliary symbol needs to satisfy
\begin{itemize}
\item[(a')] $\lim_{N\to\infty}\tilde{\Phi}_N^\wedge(n)=1$, uniformly with respect to $n=0,1,\ldots$,
\item[(b')] $\sum_{n=0}^\infty \frac{2n+1}{4\pi} \big|\tilde{\Phi}_N^\wedge(n)\big|< \infty$,  for all $N=0,1,\ldots$.
\end{itemize}

Remembering that $F_2$ is only available locally in $\Gamma_r$ and paying tribute to \eqref{eqn:Wjrr}, we define the wavelet transform 
\begin{align} {\tilde{W}_N[F_2](x)=\int_{\mathcal{C}_r(x,\rho)}\tilde{\Psi}_N(x,y) F_2(y)d\omega(y),\quad x\in\tilde{\Gamma}_r.}
\end{align}

The approximation \eqref{eqn:firstapprox2} of $U^+$ in $\tilde{\Gamma}_r$ is then modified by
\begin{align} {U_N^\ensuremath{\varepsilon}={T}_N[F_1^{\ensuremath{\varepsilon}_1}]+{\tilde{W}}_N[F_2^{\ensuremath{\varepsilon}_2}],}
\end{align}
where $\ensuremath{\varepsilon}$ stands short for $(\ensuremath{\varepsilon}_1,\ensuremath{\varepsilon}_2)^T$.

We choose these symbols to be the minimizers of the functional 
\begin{equation} {\begin{aligned}
\mathcal{F}(\Phi_N,\tilde{\Psi}_N)=&\sum_{n=0}^{\lfloor\kappa N\rfloor}\tilde{\alpha}_{N,n}\big|1-\tilde{\Phi}_{N}^\wedge(n)\big|^2+\sum_{n=0}^{N}\alpha_{N,n}\big|1-{\Phi}_{N}^\wedge(n)\sigma_n\big|^2
\\&+\beta_N\sum_{n=0}^{N}\big|\Phi_N^\wedge(n)\big|^2+8\pi^2 r^4\big\|\tilde{\Psi}_N\big\|^2_{L^2([-1,1-\rho])},
\end{aligned}}
\end{equation}
with $\Phi_N$ being a member of Pol$_{N}$ and $\tilde{\Psi}_N$ a member of Pol$_{\lfloor\kappa N\rfloor}$.

Assume that all parameters $\tilde{\alpha}_{N,n}$, $\alpha_{N,n}$, and $\beta_N$ are positive. Then there exist unique minimizers $\Phi_N\in\textnormal{Pol}_{N}$ and $\tilde{\Psi}_N\in\textnormal{Pol}_{\lfloor\kappa N\rfloor}$ of the functional $\mathcal{F}$ in \eqref{eqn:mineq2} that are determined by the symbols $\phi=(\Phi_N^\wedge(1)\sigma_1,\ldots,\Phi_N^\wedge(N)\sigma_{N},\tilde{\Phi}_{N}^\wedge(1),\ldots,\tilde{\Phi}_{N}^\wedge(\lfloor\kappa N\rfloor))^T$ which solve the linear equations
\begin{align} \mathbf{M}\phi=\alpha,
\end{align}
where 
\begin{align}
\mathbf{M}=\left(\begin{array}{c|c}\mathbf{D}_1+\mathbf{P}_1&-\mathbf{P}_2\\\hline-\mathbf{P}_3&\mathbf{D}_2+\mathbf{P}_4\end{array}\right),
\end{align}
and $\alpha=(\alpha_{N,1},\ldots,\alpha_{N,N},\tilde{\alpha}_{N,1},\ldots,\tilde{\alpha}_{N,\lfloor\kappa N\rfloor})^T$. The diagonal matrices $\mathbf{D}_1$, $\mathbf{D}_2$ are given by 
\begin{align}
\mathbf{D}_1=\textnormal{diag}\left(\frac{\beta_N}{\sigma_n^2}+\alpha_{N,n}\right)_{n=0,\ldots,N}, \qquad\mathbf{D}_2=\textnormal{diag}\big(\tilde{\alpha}_{N,n}\big)_{n=0,\ldots,\lfloor\kappa N\rfloor},
\end{align}
whereas $\mathbf{P}_1$,\ldots, $\mathbf{P}_4$ are submatrices of the Gram matrix $\big(P_{n,m}^\rho\big)_{n,m=0,\ldots, \lfloor\kappa N\rfloor}$. More precisely,
\begin{align}
\mathbf{P}_1=\big(P_{n,m}^\rho\big)_{n,m=0,\ldots,N},&\qquad \mathbf{P}_2=\big(P_{n,m}^\rho\big)_{n=0,\ldots,N\atop m=0,\ldots,\lfloor\kappa N\rfloor},
\\\mathbf{P}_3=\big(P_{n,m}^\rho\big)_{n=0,\ldots,\lfloor\kappa N\rfloor\atop m=0,\ldots,N},&\qquad\mathbf{P}_4=\big(P_{n,m}^\rho\big)_{n,m=0,\ldots,\lfloor\kappa N\rfloor}.
\end{align}
with
\begin{align}
P_{n,m}^\rho=\frac{(2n+1)(2m+1)}{2}\int_{-1}^{1-\rho}P_n(t)P_m(t)dt.
\end{align}

First we observe that the representation \eqref{eqn:psin} of the kernel $\tilde{\Psi}_N$ and its zonality together with the addition theorem for spherical harmonics imply 
\small
\begin{align} &8\pi^2 r^4\left\|\tilde{\Psi}_N\right\|^2_{L^2([-1,1-\rho])}
\\&=\frac{8\pi^2 r^4}{r^4}\int_{-1}^{1-\rho}\Bigg|\sum_{n=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{4\pi}\left(\tilde{\Phi}_{N}^\wedge(n)-\Phi_N^\wedge(n)\sigma_n\right)P_n(t)\Bigg|^2dt\nonumber
\\&=\sum_{n=0}^{\lfloor\kappa N\rfloor}\sum_{m=0}^{\lfloor\kappa N\rfloor}\frac{(2n+1)(2m+1)}{2}\left(\tilde{\Phi}_{N}^\wedge(m)-\Phi_N^\wedge(m)\sigma_m\right)\left(\tilde{\Phi}_{N}^\wedge(n)-\Phi_N^\wedge(n)\sigma_n\right)\int_{-1}^{1-\rho}\!\!\!\!\!\!\!P_n(t)P_m(t)dt\nonumber
\\&=\sum_{n=0}^{\lfloor\kappa N\rfloor}\sum_{m=0}^{\lfloor\kappa N\rfloor}\left(\tilde{\Phi}_{N}^\wedge(m)-\Phi_N^\wedge(m)\sigma_m\right)\left(\tilde{\Phi}_{N}^\wedge(n)-\Phi_N^\wedge(n)\sigma_n\right)P_{n,m}^\rho.\nonumber
\end{align}
\normalsize
Inserting \eqref{eqn:psinorm} into \eqref{eqn:mineq2} and then differentiating the whole expression with respect to $\Phi_N^\wedge(n)\sigma_n$ and $\tilde{\Phi}_{N}^\wedge(n)$ leads to 
\begin{align}
-2\alpha_{N,n}(1-\Phi_N^\wedge(n)\sigma_n)+2\beta_N\frac{\Phi_N^\wedge(n)\sigma_n}{\sigma_n^2}-2\sum_{m=0}^{\lfloor\kappa N\rfloor}\left(\tilde{\Phi}_{N}^\wedge(m)-\Phi_N^\wedge(m)\sigma_m\right)P_{n,m}^\rho,
\end{align} 
for $n=0,\ldots,N$, and
\begin{align}
-2\tilde{\alpha}_{N,n}(1-\tilde{\Phi}_{N}^\wedge(n))+2\sum_{m=0}^{\lfloor\kappa N\rfloor}\left(\tilde{\Phi}_{N}^\wedge(m)-\Phi_N^\wedge(m)\sigma_m\right)P_{n,m}^\rho,
\end{align}
for $n=0,\ldots,\lfloor\kappa N\rfloor$, respectively. Setting the two expressions above equal to zero, a proper reordering leads to the linear equation \eqref{eqn:lineq1}. At last, we observe that the matrix $(P_{n,m}^\rho)_{n,m=0,\ldots,\lfloor\kappa N\rfloor}$ is positive definite (since it represents a Gram matrix of linearly independent functions) and that all appearing diagonal matrices are positive definite due to positive matrix entries. Thus, the matrix $\mathbf{M}$ is positive definite and the linear system \eqref{eqn:lineq1} is uniquely solvable and leads to a minimum of \eqref{eqn:mineq2}.

Assume that the parameters $\alpha_{N,n}$, $\tilde{\alpha}_{N,n}$, and $\beta_N$ are positive and suppose that, for some fixed $\delta>0$ and $\kappa>1$,
\begin{align}
\inf_{n=0,\ldots, \lfloor\kappa N\rfloor}\frac{\beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^2}+( \lfloor\kappa N\rfloor+1)^2}{{\alpha}_{N,n}}&=\mathcal{O}\left(N^{-2(1+\delta)}\right),\quad \textit{ for }N\to\infty. \end{align}
The same relation shall hold true for $\tilde{\alpha}_{N,n}$. Additionally, let every $N$ be associated with an $\varepsilon_1=\varepsilon_1(N)>0$ and an $\varepsilon_2=\varepsilon_2(N)>0$ such that 
\begin{align}
\lim_{N\to\infty}\varepsilon_1 \left(\frac{R}{r}\right)^{N}=\lim_{N\to\infty}\varepsilon_2 \,{N}=0. \end{align}
The functions $F_1:\Omega_R\to\mathbb{R}$ and $F_2:\Gamma_r\to\mathbb{R}$, $r<R$, are supposed to be such that a unique solution $U$ of \eqref{eqn:11}--\eqref{eqn:13} exists and that the restriction $U^+$ is of class $\mathcal{H}_s(\Omega_r)$, for some fixed $s\geq 2$. The erroneous input data is given by $F_1^{\ensuremath{\varepsilon}_1}=F_1+\ensuremath{\varepsilon}_1 E_1$ and $F_2^{\ensuremath{\varepsilon}_2}=F_2+\ensuremath{\varepsilon}_2 E_2$, with $E_1\in L^2(\Omega_R)$ and $E_2\in L^2(\Omega_r)$. If the kernels $\Phi_N\in\textnormal{Pol}_{N}$ and kernel $\tilde{\Psi}_N\in\textnormal{Pol}_{ \lfloor\kappa N\rfloor}$ are the minimizers of the functional $\mathcal{F}$ from \eqref{eqn:mineq2} and if $U_N^\ensuremath{\varepsilon}$ is given as in \eqref{eqn:firstapprox3}, then
\begin{align}
\lim_{N\to\infty}\left\|U^+-U_ {N}^{\varepsilon}\right\|_{L^2(\tilde{\Gamma}_r)}=0. \end{align}

As an auxiliary set of kernels, we define the Shannon-type kernels $\Phi_N^{Sh}$ and $\tilde{\Psi}_N^{Sh}$ via the symbols
\begin{align}
\big(\Phi_N^{Sh}\big)^\wedge(n)=\left\{\begin{array}{ll}\frac{1}{\sigma_n},&n\leq N,\\0,&\textnormal{else},\end{array}\right.\qquad \big(\tilde{\Phi}_{N}^{Sh}\big)^\wedge(n)=\left\{\begin{array}{ll}1,&n\leq \lfloor\kappa N\rfloor,\\0,&\textnormal{else},\end{array}\right.
\end{align}
and $\big(\tilde{\Psi}_N^{Sh}\big)^\wedge(n)=\big(\tilde{\Phi}_N^{Sh}\big)^\wedge(n)-\big(\Phi_N^{Sh}\big)^\wedge(n)\sigma_n$. $\Phi_N^{Sh}$ represents the kernel of the so-called truncated singular value decomposition for the downward continuation operator ${T}^{down}$. By using the addition theorem for spherical harmonics and properties of the Legendre polynomials, we obtain
\begin{align}
\mathcal{F}(\Phi_N^{Sh},\tilde{\Psi}_N^{Sh})&=\beta_N\sum_{n=0}^{N}\frac{1}{\sigma_n^2}+8\pi^2 r^4\big\|\tilde{\Psi}_N^{Sh}\big\|^2_{L^2([-1,1-\rho])} \\&\leq \beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^{2}}+8\pi^2\sum_{n=0}^{\lfloor\kappa N\rfloor}\left(\frac{2n+1}{4\pi}\right)^2\left\|P_n\right\|^2_{L^2([-1,1])}\nonumber
\\&= \beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^{2}}+(\lfloor\kappa N\rfloor+1)^2.\nonumber
\end{align}
The kernels that minimize $\mathcal{F}$ are denoted by $\Phi_N$ and $\tilde{\Psi}_N$. In consequence,
\begin{align}
\tilde{\alpha}_{N,n}\big(1-\tilde{\Phi}_{N}^\wedge(n)\big)^2&\leq\mathcal{F}(\Phi_N,\tilde{\Psi}_N)\leq \mathcal{F}(\Phi_N^{Sh},\tilde{\Psi}_N^{Sh})
\\&\leq \beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^{2}}+(\lfloor\kappa N\rfloor+1)^2,\nonumber
\end{align}
for all $n\leq \lfloor\kappa N\rfloor$. In combination with \eqref{eqn:ass1}, this leads to
\begin{align} \big|1-\tilde{\Phi}_{N}^\wedge(n)\big|= \mathcal{O}(N^{-1-\delta}),
\end{align}
uniformly for all $n\leq \lfloor\kappa N\rfloor$ and $N\to\infty$. The estimate $|1-\Phi_N^\wedge(n)\sigma_n|=\mathcal{O}(N^{-1-\delta})$ follows in the same manner and holds uniformly for all $n\leq N$ and $N\to\infty$. Finally, since $\tilde{\Phi}_{N}^\wedge(n)=0$ for $n> \lfloor\kappa N\rfloor$, we end up with
\begin{align}
\lim_{N\to\infty}\sup_{n=0,1,\ldots}\frac{|1-\tilde{\Phi}_{N}^\wedge(n)|}{(n+\frac{1}{2})^{s}}=0,
\end{align}
which shows that the first term on the right hand side of the error estimate \eqref{eqn:errorestfinal} vanishes. The second term can be treated analogously. 

Due to the uniform boundedness of $|\Phi_J^\wedge(n)\sigma_n|$, there exists some constant $C>0$ such that \eqref{eqn:propx} implies
\begin{align}
\lim_{N\to\infty}\ensuremath{\varepsilon}_1\sup_{n=0,1,\ldots}\left|\Phi_N^\wedge(n)\right|\leq C\lim_{N\to\infty}\ensuremath{\varepsilon}_1\left(\frac{R}{r}\right)^{N}=0.
\end{align}
so that the third term on the right hand side of \eqref{eqn:errorestfinal} vanishes as well. The fourth term does not vanish. However, taking a closer look at the derivation of this term, we see that it suffices to show that $\big\|\sum_{n=0}^\infty\sum_{k=1}^{2n+1}\tilde{\Psi}_{N}^\wedge(n)F_r^\wedge(n,k)\frac{1}{r}Y_{n,k}\big\|_{L^2(\Omega_r)}$ tends to zero (where $F$ stands for $U^+$ or $E_2$). Using the previous results and $|\tilde{\Psi}_N^\wedge(n)|\leq |1-{\Phi}_N^\wedge(n)\sigma_n|+|1-\tilde{\Phi}_N^\wedge(n)|$, it follows that
\begin{align}
\left\|\sum_{n=0}^\infty\sum_{k=1}^{2n+1}\tilde{\Psi}_{N}^\wedge(n)F_r^\wedge(n,k)\frac{1}{r}Y_{n,k}\right\|_{L^2(\Omega_r)}^2\leq \mathcal{O}(N^{-2\delta})+C\sum_{n=N+1}^{\lfloor \kappa N\rfloor}\sum_{k=1}^{2n+1}\left|F_r^\wedge(n,k)\right|^2,
\end{align}
for some constant $C>0$. Latter vanishes for $N\to\infty$ since $F$ (i.e., $U^+$ or $E_2$) is of class $L^2(\Omega_r)$. In order to handle the last term of the error estimate \eqref{eqn:errorestfinal}, it has to be shown that $\|\tilde{\Psi}_N\|_{L^2([-1,1-\rho])}$ tends to zero. This, again, is generally not true. But, taking a closer look at the derivation of the estimate indicates that it suffices to show that
\small\begin{align} \Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}_{N}(\cdot,y) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}, \qquad \ensuremath{\varepsilon}_2\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}_{N}(\cdot,y) E_2(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\end{align}\normalsize
vanish as $N\to\infty$. For the left expression we obtain
\begin{equation} \begin{aligned}
&\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}_{N}(\cdot,y) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\leq\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}^{Sh}_{N}(\cdot,y) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\quad\,+\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\left(\tilde{\Psi}^{Sh}_{N}(\cdot,y)-\tilde{\Psi}_{N}(\cdot,y)\right) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\leq\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}^{Sh}_{N}(\cdot,y) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\quad\,+2\pi r^2\|\tilde{\Psi}^{Sh}_{N}-\tilde{\Psi}_{N}\|_{L^2([-1,1-\rho])} \|U^+\|_{L^1(\Omega_r)},
\end{aligned}
\end{equation}
where Young's inequality has been used in the last row. Since $U^+\in \mathcal{H}_s(\Omega_r)$, $s\geq 2$, Proposition \ref{prop:loc1} implies that the first term on the right hand side of \eqref{eqn:locest} tends to zero as $N\to\infty$. The second term on the right hand side of \eqref{eqn:locest} can be treated as follows 
\begin{equation}
\begin{aligned}
&\big\|\tilde{\Psi}^{Sh}_{N}-\tilde{\Psi}_{N}\big\|_{L^2([-1,1-\rho])}^2
\\&\leq\sum_{n=0}^{\lfloor\kappa N\rfloor}\left(\frac{2n+1}{4\pi}\right)^2\left|\tilde{\Psi}_N^\wedge(n)-\left(\tilde{\Psi}^{Sh}_N\right)^\wedge(n)\right|^2\|P_n\|_{L^2([-1,1])}^2
\\&\leq\sum_{n=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{8\pi^2}\left|\left|\tilde{\Phi}_{N}^\wedge(n)-1\right|+\left|{\Phi}_N^\wedge(n)\sigma_n-1\right|\chi_{[0,N]}(n)\right|^2
\\&=\sum_{n=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{8\pi^2}\mathcal{O}\left(N^{-2(1+\delta)}\right)=\mathcal{O}\left(N^{-2\delta}\right).
\end{aligned}
\end{equation}
By $\chi_{[0,N]}(n)$ we mean the characteristic function, i.e., it is equal to 1 if $n=0,\ldots,N$, and equal to 0 otherwise. In conclusion, the left expression in \eqref{eqn:altterms} vanishes as $N\to\infty$. For the right expression in \eqref{eqn:altterms}, we obtain the desired result in a similar but easier manner. Finally, combining all steps of the proof, we have shown that the right hand side of the error estimate \eqref{eqn:errorestfinal} converges to zero, which yields \eqref{eqn:convres}.

The condition $U^+\in \mathcal{H}_s(\Omega_r)$, $s\geq 2$, in Theorem \ref{thm:convres} can be relaxed to $U^+\in \mathcal{H}_s(\Omega_r)$, $s>0$, if the minimizing functional $\mathcal{F}$ in \eqref{eqn:mineq2} is substituted by
\begin{align} \mathcal{F}_{Filter}(\Phi_N,\tilde{\Psi}_N)=&\sum_{n=0}^{\lfloor \kappa N\rfloor}\tilde{\alpha}_{N,n}\big|K_N^\wedge(n)-\tilde{\Phi}_{N}^\wedge(n)\big|^2+\sum_{n=0}^{N}\alpha_{N,n}\big|K_N^\wedge(n)-{\Phi}_{N}^\wedge(n)\sigma_n\big|^2
\\&+\beta_N\sum_{n=0}^{N}\big|\Phi_N^\wedge(n)\big|^2+8\pi^2 r^4\left\|\tilde{\Psi}_N\right\|^2_{L^2([-1,1-\rho])},\nonumber
\end{align}
where $K_N^\wedge(n)$ are the symbols of a filtered kernel (compare, e.g., \cite{yuguang132} and references therein for more information)
\begin{align}
\tilde{\Phi}_{N}^{Filter}(x,y)=\sum_{n=0}^{N}\sum_{k=1}^{2n+1}K_N^\wedge(n)Y_{n,k}\left(\frac{x}{|x|}\right)Y_{n,k}\left(\frac{y}{|y|}\right).
\end{align}
Then the proof of Theorem \ref{thm:convres} follows in a very similar manner as before, just that the minimizing kernels are not compared to the Shannon-type kernel but to the filtered kernel. Opposed to the Shannon-type kernel, an appropriately filtered kernel has the localization property $\lim_{N\to\infty}\|\tilde{\Phi}_{N}^{Filter}\|_{L^1([-1,1-\rho])}=0$  which makes the condition $s\geq 2$ on the smoothness of $U^+$ (required for Proposition \ref{prop:loc1}) obsolete.

Assume that the parameters $\alpha_{N,n}$, $\tilde{\alpha}_{N,n}$, and $\beta_N$ are positive and suppose that, for some fixed $\delta>0$ and $\kappa>1$,
\begin{align}
\inf_{n=0,\ldots, \lfloor\kappa N\rfloor}\frac{\beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^2}+( \lfloor\kappa N\rfloor+1)^2}{{\alpha}_{N,n}}&=\mathcal{O}\left(N^{-2(1+\delta)}\right),\quad \textit{ for }N\to\infty. \end{align}
The same relation shall hold true for $\tilde{\alpha}_{N,n}$. If the scaling kernel $\Phi_N\in\textnormal{Pol}_{N}$ and the wavelet kernel $\tilde{\Psi}_N\in\textnormal{Pol}_{\lfloor\kappa N\rfloor}$ are the minimizers of the functional $\mathcal{F}$ from \eqref{eqn:mineq2}, then
\begin{align} \lim_{N\to\infty}
\frac{\big\|\tilde{\Psi}_N\big\|^2_{L^2([-1,1-\rho])}}{\big\|\tilde{\Psi}_N\big\|^2_{L^2([-1,1])}}=0.
\end{align}

The function $F_N(t)={|\tilde{\Psi}_N(t)|^2}/{\|\tilde{\Psi}_N\|^2_{L^2([-1,1])}}$ can be regarded as the density function of a random variable $t\in[-1,1]$. Thus, we can write
\begin{align}
\frac{\big\|\tilde{\Psi}_N\big\|^2_{L^2([-1,1-\rho])}}{\big\|\tilde{\Psi}_N\big\|^2_{L^2([-1,1])}}&=\int_{-1}^{1-\rho}F_N(t)dt=P_N(t< 1-\rho)=1-P_N\big(t-E_N(t)\geq 1-\rho-E_N(t)\big)\nonumber
\\&\leq \frac{V_N(t)}{V_N(t)+ (1-\rho-E_N(t))^2},
\end{align}
where we have used Cantelli's inequality for the last estimate. By $P_N(t< a)$ we mean the probability (with respect to the density function $F_N$) that $t$ lies in the interval $[-1,a)$ while $P_N(t\geq a)$ means the probability of $t$ being in the interval $[a,1]$. Furthermore, $E_N(t)$ denotes the expected value of $t$ and $V_N(t)=E(t^2)-(E(t))^2$ the variance of $t$. In other words, we are done if we can show that $\lim_{N\to\infty}E_N(t)=1$ and $\lim_{N\to \infty}V_N(t)=0$. 

First, we use the addition theorem for spherical harmonics and the recurrence relation  $tP_n(t)=\frac{1}{2n+1}\left((n+1)P_{n+1}(t)+nP_{n-1}(t)\right)$ to obtain  
\begin{align} \int_{-1}^1 t|\tilde{\Psi}_N(t)|^2 dt&= \frac{1}{r^2} \sum_{n=0}^{\lfloor\kappa N\rfloor}\sum_{m=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{4\pi}\frac{2m+1}{4\pi}\tilde{\Psi}_N^\wedge(n)\tilde{\Psi}_N^\wedge(m)\int_{-1}^1tP_n(t)P_m(t)dt
\\&=\sum_{n=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{16\pi^2r^2}\tilde{\Psi}_N^\wedge(n)\left(n\tilde{\Psi}_N^\wedge(n-1)+(n+1)\tilde{\Psi}_N^\wedge(n+1)\right)\int_{-1}^1|P_n(t)|^2 dt\nonumber
\\&=\frac{1}{8\pi^2r^2}\sum_{n=0}^{\lfloor\kappa N\rfloor}n\tilde{\Psi}_N^\wedge(n)\tilde{\Psi}_N^\wedge(n-1)+(n+1)\tilde{\Psi}_N^\wedge(n)\tilde{\Psi}_N^\wedge(n+1).\nonumber
\end{align}
From \eqref{eqn:conphij} and the corresponding estimate for $\Phi_N^\wedge(n)\sigma_n$ we find $|\tilde{\Psi}_N^\wedge(n)|^2=\mathcal{O}(N^{-2(1+\delta)})$ for $n\leq N$, and $|1-\tilde{\Psi}_N^\wedge(n)|^2=|1-\tilde{\Phi}_{N}^\wedge(n)|^2=\mathcal{O}(N^{-2(1+\delta)})$, for $N+1\leq n\leq \lfloor\kappa N\rfloor$. As a consequence,  \eqref{eqn:et1} implies
\begin{align} &\int_{-1}^1 t|\tilde{\Psi}_N(t)|^2 dt
\\&=\mathcal{O}(N^{-2\delta})+\sum_{n=N+1}^{\lfloor\kappa N\rfloor} \frac{2n+1}{8\pi^2r^2}|\tilde{\Psi}_N^\wedge(n)|^2\left(\frac{n}{2n+1}\frac{\tilde{\Psi}_N^\wedge(n-1)}{\tilde{\Psi}_N^\wedge(n)}+\frac{n+1}{2n+1}\frac{\tilde{\Psi}_N^\wedge(n+1)}{\tilde{\Psi}_N^\wedge(n)}\right),\nonumber
\end{align}
where $\sup_{N+1\leq n\leq\lfloor \kappa N\rfloor}\big|1-\big(\frac{n}{2n+1}{\tilde{\Psi}_N^\wedge(n-1)}/{\tilde{\Psi}_N^\wedge(n)}+\frac{n+1}{2n+1}{\tilde{\Psi}_N^\wedge(n+1)}/{\tilde{\Psi}_N^\wedge(n)}\big)\big|\leq\varepsilon_N$, for  some $\varepsilon_N>0$ that satisfies $\varepsilon_N\to0$ as $N\to\infty$. The term $\|\tilde{\Psi}_N\|_{L^2([-1,1])}^2$ can be expressed similarly by
\begin{align} \|\tilde{\Psi}_N\|_{L^2([-1,1])}^2=\sum_{n=0}^{\lfloor\kappa N\rfloor} \frac{2n+1}{8\pi^2r^2}|\tilde{\Psi}_N^\wedge(n)|^2=\mathcal{O}(N^{-2\delta})+\sum_{n=N+1}^{\lfloor\kappa N\rfloor} \frac{2n+1}{8\pi^2r^2}|\tilde{\Psi}_N^\wedge(n)|^2.
\end{align}
Thus, combining \eqref{eqn:et1}--\eqref{eqn:et2}, we obtain
\begin{align}
\lim_{N\to\infty}E_N(t)=\lim_{N\to\infty}\int_{-1}^1 t|F_N(t)| dt=\lim_{N\to\infty}\frac{\int_{-1}^1 t|\tilde{\Psi}_N(t)|^2 dt}{\|\tilde{\Psi}_N\|_{L^2([-1,1])}^2}=1.
\end{align}
In a similar fashion it can be shown that $\lim_{N\to\infty}E_N(t^2)=1$, implying $\lim_{N\to\infty}V_N(t)=0$, which concludes the proof.

Thus, we are not confronted with the scalar equations \eqref{eqn:11}--\eqref{eqn:13} but with the vectorial problem
\begin{align}
b=\nabla U,&\quad \textnormal{in }\Omega_r^{ext}, \\\Delta U=0,&\quad \textnormal{in }\Omega_r^{ext}, \\b=f_1,&\quad \textnormal{on }\Omega_R, \\b=f_2,&\quad \textnormal{on }\Gamma_r. \end{align}

Here, we mainly follow the course of \cite{freeschrei09} and use the following set of vector spherical harmonics:
\begin{align}
{y}_{n,k}^{(1)}\left(\xi\right)&=\xi Y_{n,k}\left(\xi\right), \\{y}_{n,k}^{(2)}\left(\xi\right)&=\frac{1}{\sqrt{n(n+1)}}\nabla^*_{\xi}Y_{n,k}\left(\xi\right),
\\{y}_{n,k}^{(3)}\left(\xi\right)&=\frac{1}{\sqrt{n(n+1)}}L_{\xi}^*Y_{n,k}\left(\xi\right), \end{align}
for $n=1,2,\ldots$, and $k=1,\ldots, 2n+1$, with ${y}_{n,k}^{(1)}$ additionally being defined for $n=0$ and $k=1$.

They are complemented by a set of tensorial Legendre polynomials $\mathbf{P}^{(i,i)}_n$ of degree $n$ and type $(i,i)$ that are defined via
\begin{align}
\mathbf{P}^{(1,1)}_n\left(\xi,\eta\right)&=\xi\otimes\eta \,P_n\left(\xi\cdot\eta\right),
\\\mathbf{P}^{(2,2)}_n\left(\xi,\eta\right)&=\frac{1}{{n(n+1)}}\nabla^*_{\xi}\otimes\nabla^*_{\eta}P_n\left(\xi\cdot\eta\right),
\\\mathbf{P}^{(3,3)}_n\left(\xi,\eta\right)&=\frac{1}{{n(n+1)}}L^*_{\xi}\otimes L^*_{\eta}P_n\left(\xi\cdot\eta\right).
\end{align}

The vectorial counterpart to the Sobolev space $\mathcal{H}_s(\Omega_r)$ is defined as
\begin{align} \mathfrak{h}_s(\Omega_r)=\Big\{f\in l^2(\Omega_r) :\|f\|_{\mathfrak{h}_s(\Omega_r)}^2=\sum_{i=1}^2\sum_{n=0_i}^\infty\sum_{k=1}^{2n+1}\left(n+\textnormal{\footnotesize$\frac{1}{2}$}\right)^{2s}\big|({f}_r^{(i)})^\wedge(n,k)\big|^2<\infty\Big\},
\end{align}
where $0_i=0$ if $i=1$ and $0_i=1$ if $i=2$, and $({f}_r^{(i)})^\wedge(n,k)$ denotes the Fourier coefficient of degree $n$, order $k$, and type $i$, i.e.,
\begin{align}
({f}_r^{(i)})^\wedge(n,k)=\int_{\Omega_r}f(y)\cdot \frac{1}{r}y_{n,k}^{(i)}\left(\frac{y}{|y|}\right)d\omega(y).
\end{align}

The space of band-limited tensorial kernels with maximal degree $N$ is defined as
\small\begin{align} \mathbf{Pol}_{N}=\left\{\mathbf{K}(x,y)=\sum_{i=1}^2\sum_{n=0_i}^{N}\sum_{k=1}^{2n+1}\mathbf{K}^\wedge(n) {y}^{(i)}_{n,k}\left(\xi\right)\otimes{y}^{(i)}_{n,k}\left(\eta\right):\mathbf{K}^\wedge(n)\in\mathbb{R}\right\}.
\end{align}

The downward continuation operator can be approximated by a bounded operator $t_N:l^2(\Omega_R)\to l^2(\Omega_r)$:
\begin{align}
{t_N[f_1](x)=\int_{\Omega_R}\mathbf{\Phi}_N(x,y) f_1(y)d\omega(y),\quad x\in\Omega_r,}
\end{align}
with
\begin{align}
{\mathbf{\Phi}_N(x,y)=\sum_{i=1}^2\sum_{n=0_i}^{N}\sum_{k=1}^{2n+1}\mathbf{\Phi}_{N}^\wedge(n)\frac{1}{r}{y}^{(i)}_{n,k}\left(\xi\right)\otimes \frac{1}{R}{y}^{(i)}_{n,k}\left(\eta\right).} \end{align}

A refinement by local data in $\Gamma_r$ is achieved by the vectorial wavelet operator $\tilde{{w}}_N:l^2({\Gamma}_r)\to l^2(\tilde{\Gamma}_r)$:
\begin{align} {\tilde{{w}}_N[f_2](x)=\int_{\mathcal{C}_r(x,\rho)}\tilde{\mathbf{\Psi}}_N(x,y) f_2(y)d\omega(y),\quad x\in\tilde{\Gamma}_r,}
\end{align}
with
\begin{align}
{\tilde{\mathbf{\Psi}}_N(x,y)=\sum_{i=1}^2\sum_{n=0_i}^{\lfloor\kappa N\rfloor}\sum_{k=1}^{2n+1}\tilde{ \mathbf{\Psi}}_{N}^\wedge(n)\frac{1}{r}{y}^{(i)}_{n,k}\left(\xi\right)\otimes \frac{1}{r}{y}^{(i)}_{n,k}\left(\eta\right)}, \end{align}
for some fixed $\kappa>1$, and 
\begin{align}
{\tilde{ \mathbf{\Psi}}_{N}^\wedge(n)=\tilde{ \mathbf{\Phi}}_{N}^\wedge(n)-\mathbf{\Phi}_{N}^\wedge(n)\sigma_n.}
\end{align}

An approximation of $b^+$ in $\tilde{\Gamma}_r$ is then defined by
\begin{align} {b_N^{\ensuremath{\varepsilon}}={t}_{N}[f_1^{\ensuremath{\varepsilon}_1}]+\tilde{{w}}_{N}[f_2^{\ensuremath{\varepsilon}_2}].}
\end{align}

A similar error estimate as in \eqref{eqn:errorestfinal} motivates the minimization of the functional
\begin{equation} {\begin{aligned}
\mathcal{F}(\mathbf{\Phi}_N,\tilde{\mathbf{\Psi}}_N)=&\sum_{n=0}^{\lfloor\kappa N\rfloor}\tilde{\alpha}_{N,n}\big|1-\tilde{\mathbf{\Phi}}_{N}^\wedge(n)\big|^2+\sum_{n=0}^{N}\alpha_{N,n}\big|1-{\mathbf{\Phi}}_{N}^\wedge(n)\sigma_n\big|^2
\\&+\beta_N\sum_{n=0}^{N}\big|\mathbf{\Phi}_N^\wedge(n)\big|^2+8\pi^2 r^4\big\|\tilde{\mathbf{\Psi}}_N\big\|^2_{L^2([-1,1-\rho])}.
\end{aligned}}
\end{equation}

Assume that all parameters $\tilde{\alpha}_{N,n}$, $\alpha_{N,n}$, and $\beta_N$ are positive. Then there exists unique minimizers $\mathbf{\Phi}_N\in\textnormal{\textbf{Pol}}_{N}$ and $\tilde{\mathbf{\Psi}}_N\in\textnormal{\textbf{Pol}}_{\lfloor\kappa N\rfloor}$ of the functional $\mathcal{F}$ in \eqref{eqn:mineq4} that are determined by $\phi=(\mathbf{\Phi}_N^\wedge(1)\sigma_1,\ldots,\mathbf{\Phi}_N^\wedge(N)\sigma_{N},\tilde{\mathbf{\Phi}}_{N}^\wedge(1),\ldots,\tilde{\mathbf{\Phi}}_{N}^\wedge(\lfloor\kappa N\rfloor))^T$ which solves the linear equations
\begin{align} \mathbf{M}{\phi}=\alpha,
\end{align}
where 
\begin{align}
\mathbf{M}=\left(\begin{array}{c|c}\mathbf{D}_1+\mathbf{P}_1&-\mathbf{P}_2\\\hline-\mathbf{P}_3&\mathbf{D}_2+\mathbf{P}_4\end{array}\right),
\end{align}
and $\alpha=(\alpha_{N,1},\ldots,\alpha_{N,N},\tilde{\alpha}_{N,1},\ldots,\tilde{\alpha}_{N,\lfloor\kappa N\rfloor})^T$. The diagonal matrices $\mathbf{D}_1$, $\mathbf{D}_2$ are given by 
\begin{align}
\mathbf{D}_1=\textnormal{diag}\left(\frac{\beta_N}{\sigma_n^2}+\alpha_{N,n}\right)_{n=0,\ldots,N}, \qquad\mathbf{D}_2=\textnormal{diag}\big(\tilde{\alpha}_{N,n}\big)_{n=0,\ldots,\lfloor\kappa N\rfloor},
\end{align}
whereas $\mathbf{P}_1$,\ldots, $\mathbf{P}_4$ are submatrices of the Gram matrix $\big(P_{n,m}^\rho\big)_{n,m=0,\ldots, \lfloor\kappa N\rfloor}$. More precisely,
\begin{align}
\mathbf{P}_1=\big(P_{n,m}^\rho\big)_{n,m=0,\ldots,N},&\qquad \mathbf{P}_2=\big(P_{n,m}^\rho\big)_{n=0,\ldots,N\atop m=0,\ldots,N\lfloor\kappa N\rfloor},
\\\mathbf{P}_3=\big(P_{n,m}^\rho\big)_{n=0,\ldots,\lfloor\kappa N\rfloor\atop m=0,\ldots,N},&\qquad\mathbf{P}_4=\big(P_{n,m}^\rho\big)_{n,m=0,\ldots,\lfloor\kappa N\rfloor}.
\end{align}
with
\small\begin{align}
P_{n,m}^\rho=&\frac{(2n+1)(2m+1)}{16\pi^2}\int_{-1}^{1-\rho}P_n\left(t\right)P_m\left(t\right)dt
\\&+\frac{(2n+1)(2m+1)}{16\pi^2n(n+1)m(m+1)}\bigg(\int_{-1}^{1-\rho}(1+t^2)P_n'(t)P_m'(t)dt+\int_{-1}^{1-\rho}(1-t^2)^2P_n''(t)P_m''(t)dt\nonumber
\\&\quad-\int_{-1}^{1-\rho}t(1-t^2)P_n''(t)P_m'(t)dt-\int_{-1}^{1-\rho}t(1-t^2)P_n'(t)P_m''(t)dt\bigg),\nonumber
\end{align}\normalsize
for $n\not=0$ and $m\not=0$. If $n=0$ or $m=0$, then $P_{n,m}^\rho=\frac{(2n+1)(2m+1)}{16\pi^2}\int_{-1}^{1-\rho}P_n\left(t\right)P_m\left(t\right)dt$. By $P_n'$, $P_n''$ we mean the first and second order derivatives of the Legendre polynomials.

Assume that parameters $\alpha_{N,n}$, $\tilde{\alpha}_{N,n}$, and $\beta_N$ are positive and suppose that, for some $\delta>0$ and $\kappa>1$,
\begin{align}
\inf_{n=0,\ldots, \lfloor \kappa N\rfloor}\frac{\beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^2}+(\lfloor \kappa N\rfloor+1)^2}{{\alpha}_{N,n}}&=\mathcal{O}\left(N^{-2(1+\delta)}\right),\quad \textit{ for }N\to\infty. \end{align}
An analogous relation shall hold true for $\tilde{\alpha}_{N,n}$. Additionally, let every $N$ be associated with an $\varepsilon_1=\varepsilon_1(N)>0$ and an $\varepsilon_2=\varepsilon_2(N)>0$ such that 
\begin{align}
\lim_{N\to\infty}\varepsilon_1 \left(\frac{R}{r}\right)^{N}=\lim_{N\to\infty}\varepsilon_2\, {N}=0. \end{align}
The functions $f_1:\Omega_R\to\mathbb{R}^3$ and $f_2:\Gamma_r\to\mathbb{R}^3$, $r<R$, are supposed to be such that a unique solution $b$ of \eqref{eqn:bvp441}--\eqref{eqn:bvp444} exists and that the restriction $b^+$ is of class $\mathfrak{h}_s(\Omega_r)$, for some fixed $s\geq 2$. The erroneous input data is given by $f_1^{\ensuremath{\varepsilon}_1}=f_1+\ensuremath{\varepsilon}_1 e_1$ and $f_2^{\ensuremath{\varepsilon}_2}=f_2+\ensuremath{\varepsilon}_1 e_2$, with $e_1\in l^2(\Omega_R)$ and $e_2\in l^2(\Omega_r)$. If the kernels $\mathbf{\Phi}_N\in\textnormal{\textbf{Pol}}_{N}$ and the wavelet kernel $\tilde{\mathbf{\Psi}}_N\in\textnormal{\textbf{Pol}}_{\lfloor \kappa N\rfloor}$ are the minimizers of the functional $\mathcal{F}$ from \eqref{eqn:mineq4} and if $b_N^\ensuremath{\varepsilon}$ is given as in \eqref{eqn:approxbj3}, then
\begin{align}
\lim_{N\to\infty}\left\|b^+-b_ {N}^{\varepsilon}\right\|_{l^2(\tilde{\Gamma}_r)}=0. \end{align}

Assume that the parameters $\alpha_{N,n}$, $\tilde{\alpha}_{N,n}$, and $\beta_N$ are positive and suppose that, for some $\delta>0$ and $\kappa>1$,
\begin{align}
\inf_{n=0,\ldots, \lfloor \kappa N\rfloor}\frac{\beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^2}+(\lfloor \kappa N\rfloor+1)^2}{{\alpha}_{N,n}}&=\mathcal{O}\left(N^{-2(1+\delta)}\right),\quad \textit{ for }N\to\infty. \end{align}
An analogous relation shall hold true for $\tilde{\alpha}_{N,n}$. If the scaling kernel $\mathbf{\Phi}_N\in\textnormal{\textbf{Pol}}_{N}$ and the wavelet kernel $\tilde{\mathbf{\Psi}}_N\in\textnormal{\textbf{Pol}}_{\lfloor \kappa N\rfloor}$ are the minimizers of the functional $\mathcal{F}$ from \eqref{eqn:mineq4}, then
\begin{align} \lim_{N\to\infty}\frac{\big\|\tilde{\mathbf{\Psi}}_N\big\|^2_{L^2([-1,1-\rho])}}{\big\|\tilde{\mathbf{\Psi}}_N\big\|^2_{L^2([-1,1])}}=0.
\end{align}

Inserting \eqref{eqn:psinorm} into \eqref{eqn:mineq2} and then differentiating the whole expression with respect to $\Phi_N^\wedge(n)\sigma_n$ and $\tilde{\Phi}_{N}^\wedge(n)$ leads to 
\begin{align}
-2\alpha_{N,n}(1-\Phi_N^\wedge(n)\sigma_n)+2\beta_N\frac{\Phi_N^\wedge(n)\sigma_n}{\sigma_n^2}-2\sum_{m=0}^{\lfloor\kappa N\rfloor}\left(\tilde{\Phi}_{N}^\wedge(m)-\Phi_N^\wedge(m)\sigma_m\right)P_{n,m}^\rho,
\end{align} 
for $n=0,\ldots,N$, and
\begin{align}
-2\tilde{\alpha}_{N,n}(1-\tilde{\Phi}_{N}^\wedge(n))+2\sum_{m=0}^{\lfloor\kappa N\rfloor}\left(\tilde{\Phi}_{N}^\wedge(m)-\Phi_N^\wedge(m)\sigma_m\right)P_{n,m}^\rho,
\end{align}
for $n=0,\ldots,\lfloor\kappa N\rfloor$, respectively. Setting the two expressions above equal to zero, a proper reordering leads to the linear equation \eqref{eqn:lineq1}.

As an auxiliary set of kernels, we define the Shannon-type kernels $\Phi_N^{Sh}$ and $\tilde{\Psi}_N^{Sh}$ via the symbols
\begin{align}
\big(\Phi_N^{Sh}\big)^\wedge(n)=\left\{\begin{array}{ll}\frac{1}{\sigma_n},&n\leq N,\\0,&\textnormal{else},\end{array}\right.\qquad \big(\tilde{\Phi}_{N}^{Sh}\big)^\wedge(n)=\left\{\begin{array}{ll}1,&n\leq \lfloor\kappa N\rfloor,\\0,&\textnormal{else},\end{array}\right.
\end{align}
and $\big(\tilde{\Psi}_N^{Sh}\big)^\wedge(n)=\big(\tilde{\Phi}_N^{Sh}\big)^\wedge(n)-\big(\Phi_N^{Sh}\big)^\wedge(n)\sigma_n$. $\Phi_N^{Sh}$ represents the kernel of the so-called truncated singular value decomposition for the downward continuation operator ${T}^{down}$.

By using the addition theorem for spherical harmonics and properties of the Legendre polynomials, we obtain
\begin{align}
\mathcal{F}(\Phi_N^{Sh},\tilde{\Psi}_N^{Sh})&=\beta_N\sum_{n=0}^{N}\frac{1}{\sigma_n^2}+8\pi^2 r^4\big\|\tilde{\Psi}_N^{Sh}\big\|^2_{L^2([-1,1-\rho])} \\&\leq \beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^{2}}+8\pi^2\sum_{n=0}^{\lfloor\kappa N\rfloor}\left(\frac{2n+1}{4\pi}\right)^2\left\|P_n\right\|^2_{L^2([-1,1])}\nonumber
\\&= \beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^{2}}+(\lfloor\kappa N\rfloor+1)^2.\nonumber
\end{align}

The kernels that minimize $\mathcal{F}$ are denoted by $\Phi_N$ and $\tilde{\Psi}_N$. In consequence,
\begin{align}
\tilde{\alpha}_{N,n}\big(1-\tilde{\Phi}_{N}^\wedge(n)\big)^2&\leq\mathcal{F}(\Phi_N,\tilde{\Psi}_N)\leq \mathcal{F}(\Phi_N^{Sh},\tilde{\Psi}_N^{Sh})
\\&\leq \beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^{2}}+(\lfloor\kappa N\rfloor+1)^2,\nonumber
\end{align}
for all $n\leq \lfloor\kappa N\rfloor$.

Finally, since $\tilde{\Phi}_{N}^\wedge(n)=0$ for $n> \lfloor\kappa N\rfloor$, we end up with
\begin{align}
\lim_{N\to\infty}\sup_{n=0,1,\ldots}\frac{|1-\tilde{\Phi}_{N}^\wedge(n)|}{(n+\frac{1}{2})^{s}}=0,
\end{align}
which shows that the first term on the right hand side of the error estimate \eqref{eqn:errorestfinal} vanishes. The second term can be treated analogously.

Due to the uniform boundedness of $|\Phi_J^\wedge(n)\sigma_n|$, there exists some constant $C>0$ such that \eqref{eqn:propx} implies
\begin{align}
\lim_{N\to\infty}\ensuremath{\varepsilon}_1\sup_{n=0,1,\ldots}\left|\Phi_N^\wedge(n)\right|\leq C\lim_{N\to\infty}\ensuremath{\varepsilon}_1\left(\frac{R}{r}\right)^{N}=0.
\end{align}
so that the third term on the right hand side of \eqref{eqn:errorestfinal} vanishes as well.

The fourth term does not vanish. However, taking a closer look at the derivation of this term, we see that it suffices to show that $\big\|\sum_{n=0}^\infty\sum_{k=1}^{2n+1}\tilde{\Psi}_{N}^\wedge(n)F_r^\wedge(n,k)\frac{1}{r}Y_{n,k}\big\|_{L^2(\Omega_r)}$ tends to zero (where $F$ stands for $U^+$ or $E_2$). Using the previous results and $|\tilde{\Psi}_N^\wedge(n)|\leq |1-{\Phi}_N^\wedge(n)\sigma_n|+|1-\tilde{\Phi}_N^\wedge(n)|$, it follows that
\begin{align}
\left\|\sum_{n=0}^\infty\sum_{k=1}^{2n+1}\tilde{\Psi}_{N}^\wedge(n)F_r^\wedge(n,k)\frac{1}{r}Y_{n,k}\right\|_{L^2(\Omega_r)}^2\leq \mathcal{O}(N^{-2\delta})+C\sum_{n=N+1}^{\lfloor \kappa N\rfloor}\sum_{k=1}^{2n+1}\left|F_r^\wedge(n,k)\right|^2,
\end{align}
for some constant $C>0$. Latter vanishes for $N\to\infty$ since $F$ (i.e., $U^+$ or $E_2$) is of class $L^2(\Omega_r)$.

For the left expression we obtain
\begin{equation} \begin{aligned}
&\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}_{N}(\cdot,y) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\leq\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}^{Sh}_{N}(\cdot,y) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\quad\,+\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\left(\tilde{\Psi}^{Sh}_{N}(\cdot,y)-\tilde{\Psi}_{N}(\cdot,y)\right) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\leq\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}^{Sh}_{N}(\cdot,y) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\quad\,+2\pi r^2\|\tilde{\Psi}^{Sh}_{N}-\tilde{\Psi}_{N}\|_{L^2([-1,1-\rho])} \|U^+\|_{L^1(\Omega_r)},
\end{aligned}
\end{equation}
where Young's inequality has been used in the last row.

The second term on the right hand side of \eqref{eqn:locest} can be treated as follows 
\begin{equation}
\begin{aligned}
&\big\|\tilde{\Psi}^{Sh}_{N}-\tilde{\Psi}_{N}\big\|_{L^2([-1,1-\rho])}^2
\\&\leq\sum_{n=0}^{\lfloor\kappa N\rfloor}\left(\frac{2n+1}{4\pi}\right)^2\left|\tilde{\Psi}_N^\wedge(n)-\left(\tilde{\Psi}^{Sh}_N\right)^\wedge(n)\right|^2\|P_n\|_{L^2([-1,1])}^2
\\&\leq\sum_{n=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{8\pi^2}\left|\left|\tilde{\Phi}_{N}^\wedge(n)-1\right|+\left|{\Phi}_N^\wedge(n)\sigma_n-1\right|\chi_{[0,N]}(n)\right|^2
\\&=\sum_{n=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{8\pi^2}\mathcal{O}\left(N^{-2(1+\delta)}\right)=\mathcal{O}\left(N^{-2\delta}\right).
\end{aligned}
\end{equation}
By $\chi_{[0,N]}(n)$ we mean the characteristic function, i.e., it is equal to 1 if $n=0,\ldots,N$, and equal to 0 otherwise.

The function $F_N(t)={|\tilde{\Psi}_N(t)|^2}/{\|\tilde{\Psi}_N\|^2_{L^2([-1,1])}}$ can be regarded as the density function of a random variable $t\in[-1,1]$. Thus, we can write
\begin{align}
\frac{\big\|\tilde{\Psi}_N\big\|^2_{L^2([-1,1-\rho])}}{\big\|\tilde{\Psi}_N\big\|^2_{L^2([-1,1])}}&=\int_{-1}^{1-\rho}F_N(t)dt=P_N(t< 1-\rho)=1-P_N\big(t-E_N(t)\geq 1-\rho-E_N(t)\big)\nonumber
\\&\leq \frac{V_N(t)}{V_N(t)+ (1-\rho-E_N(t))^2},
\end{align}
where we have used Cantelli's inequality for the last estimate. By $P_N(t< a)$ we mean the probability (with respect to the density function $F_N$) that $t$ lies in the interval $[-1,a)$ while $P_N(t\geq a)$ means the probability of $t$ being in the interval $[a,1]$. Furthermore, $E_N(t)$ denotes the expected value of $t$ and $V_N(t)=E(t^2)-(E(t))^2$ the variance of $t$.

The term $\|\tilde{\Psi}_N\|_{L^2([-1,1])}^2$ can be expressed similarly by
\begin{align} \|\tilde{\Psi}_N\|_{L^2([-1,1])}^2=\sum_{n=0}^{\lfloor\kappa N\rfloor} \frac{2n+1}{8\pi^2r^2}|\tilde{\Psi}_N^\wedge(n)|^2=\mathcal{O}(N^{-2\delta})+\sum_{n=N+1}^{\lfloor\kappa N\rfloor} \frac{2n+1}{8\pi^2r^2}|\tilde{\Psi}_N^\wedge(n)|^2.
\end{align}

Thus, combining \eqref{eqn:et1}--\eqref{eqn:et2}, we obtain
\begin{align}
\lim_{N\to\infty}E_N(t)=\lim_{N\to\infty}\int_{-1}^1 t|F_N(t)| dt=\lim_{N\to\infty}\frac{\int_{-1}^1 t|\tilde{\Psi}_N(t)|^2 dt}{\|\tilde{\Psi}_N\|_{L^2([-1,1])}^2}=1.
\end{align}

Taking a closer look at the terms of type $i=1$ in \eqref{eqn:vectloceq1}, using the orthogonality of $\xi$ and $\nabla^*_\xi$, we obtain
\begin{align}
&\sum_{k=1}^{2n+1}\frac{1}{r}y_{n,k}^{(1)}\left(\xi\right)\int\limits_{\Omega_r\setminus\mathcal{C}_r(x,\rho)}\frac{1}{r}y_{n,k}^{(1)}\left(\eta\right)\cdot f(r\eta)d\omega(r\eta) \\&=\sum_{k=1}^{2n+1}\frac{1}{r}y_{n,k}^{(1)}\left(\xi\right)\int\limits_{\Omega_r\setminus\mathcal{C}_r(x,\rho)}\frac{1}{r}y_{n,k}^{(1)}\left(\eta\right)\cdot \left(\eta F_1(r\eta)+\nabla^*_{\eta}F_2(r\eta)\right)d\omega(r\eta)\nonumber
\\&=\sum_{k=1}^{2n+1}\frac{1}{r^2}\xi Y_{n,k}\left(\xi\right)\int\limits_{\Omega_r\setminus\mathcal{C}_r(x,\rho)}Y_{n,k}\left(\eta\right)F_1(r\eta)d\omega(r\eta)\nonumber
\\&=\frac{1}{r^2}\xi\int\limits_{\Omega_r\setminus\mathcal{C}_r(x,\rho)}\frac{2n+1}{4\pi}P_n\left(\xi\cdot\eta\right)F_1(r\eta)d\omega(r\eta).\nonumber
\end{align}

Now, we can use the scalar localization result from Proposition \ref{prop:loc} to obtain 
\begin{align}
\lim_{N\to\infty}\Bigg\|\frac{\cdot}{|\cdot|}\int\limits_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\Bigg(\underbrace{\sum_{n=N+1}^{\lfloor\kappa N\rfloor}\frac{2n+1}{4\pi r^2}P_n\left(\frac{\cdot}{|\cdot|}\cdot\eta\right)}_{=\tilde{\Psi}_N^{Sh}(\cdot,y)}\Bigg)F_1(r\eta)d\omega(r\eta)\Bigg\|_{l^2(\Omega_r)}=0
\end{align}
and
\begin{align}
\lim_{N\to\infty}\Bigg\|\int\limits_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\left(\sum_{n=N+1}^{\lfloor\kappa N\rfloor}\frac{2n+1}{4\pi r^2}P_n\left(\frac{\cdot}{|\cdot|}\cdot\eta\right) \right)L_{\eta}^*F_2(r\eta)d\omega(r\eta)\Bigg\|_{l^2(\Omega_r)}=0,
\end{align}
which deals with the relevant contributions to the asymptotic behaviour of \eqref{eqn:eqn1} and \eqref{eqn:shit}.

Together with
\begin{align} \|\tilde{\mathbf{\Psi}}_N\|_{L^2([-1,1])}^2=\sum_{n=0}^{\lfloor \kappa N\rfloor} \frac{2n+1}{4\pi^2r^2}|\tilde{\mathbf{\Psi}}_N^\wedge(n)|^2=\mathcal{O}(N^{-2\delta})+\sum_{n=N+1}^{\lfloor \kappa N\rfloor} \frac{2n+1}{4\pi^2r^2}|\tilde{\mathbf{\Psi}}_N^\wedge(n)|^2,
\end{align}
this leads to the desired property
\begin{align}
\lim_{N\to\infty}E_N(t)=\lim_{N\to\infty}\int_{-1}^1 t|F_N(t)|^2 dt=\lim_{N\to\infty}\frac{\int_{-1}^1 t|\tilde{\Psi}_N(t)|^2 dt}{\|\tilde{\mathbf{\Psi}}_N\|_{L^2([-1,1])}^2}=1,
\end{align}
concluding the proof.
